// Extraire les paramètres de la requête
const input = $input.first().json;
const query = input.query || {};

const traite = query.traite || null;
const targetLanguage = query.target_language || 'fr';
const discord = query.discord_webhook || null;

return [{
  json: {
    traite: traite,
    targetLanguage: targetLanguage,
    discord: discord ? { webhook_url: discord } : null,
    hasTraite: !!traite
  }
}];

// Formater la réponse pour un traité spécifique
const input = $input.first().json;
const params = $('Parse Parameters').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Erreur API Torah',
        status: 'API_ERROR'
      }
    }
  }];
}

// Calculer les statistiques
const pages = data.pages || [];
const totalPages = pages.length;
const translatedPages = pages.filter(p => p.translated === true).length;
const pendingPages = pages.filter(p => p.translated === false);
const percentage = totalPages > 0 ? Math.round((translatedPages / totalPages) * 100) : 0;

// Construire la réponse
const response = {
  success: true,
  type: 'traite_detail',
  traite: data.traite || params.traite,
  target_language: params.targetLanguage,
  statistics: {
    total_pages: totalPages,
    translated: translatedPages,
    pending: totalPages - translatedPages,
    percentage: percentage
  },
  pages: pages.map(p => ({
    page: p.page,
    translated: p.translated,
    source_text_id: p.source_text_id || null,
    translation_id: p.translation_id || null,
    quality_score: p.quality_score || null,
    status: p.status || null
  })),
  pending_pages: pendingPages.map(p => p.page),
  discord: params.discord
};

return [{ json: response }];

// Formater la réponse globale (tous les traités)
const input = $input.first().json;
const params = $('Parse Parameters').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Erreur API Torah',
        status: 'API_ERROR'
      }
    }
  }];
}

// Traiter les traités
const traites = data.traites || data || [];
const traitesList = Array.isArray(traites) ? traites : [];

// Calculer les statistiques globales
let totalTexts = 0;
let translatedTexts = 0;

const formattedTraites = traitesList.map(t => {
  const total = t.total_pages || t.total || 0;
  const translated = t.translated_pages || t.translated || 0;
  const pct = total > 0 ? Math.round((translated / total) * 100) : 0;

  totalTexts += total;
  translatedTexts += translated;

  return {
    name: t.traite || t.name,
    total_pages: total,
    translated: translated,
    pending: total - translated,
    percentage: pct,
    status: pct === 100 ? 'complete' : (pct > 0 ? 'in_progress' : 'not_started')
  };
});

// Trier par pourcentage (moins traduits en premier)
formattedTraites.sort((a, b) => a.percentage - b.percentage);

const globalPercentage = totalTexts > 0 ? Math.round((translatedTexts / totalTexts) * 100) : 0;

// Construire la réponse
const response = {
  success: true,
  type: 'global_overview',
  target_language: params.targetLanguage,
  statistics: {
    total_traites: formattedTraites.length,
    total_pages: totalTexts,
    translated: translatedTexts,
    pending: totalTexts - translatedTexts,
    percentage: globalPercentage
  },
  traites: formattedTraites,
  traites_complete: formattedTraites.filter(t => t.status === 'complete').map(t => t.name),
  traites_in_progress: formattedTraites.filter(t => t.status === 'in_progress').map(t => t.name),
  traites_not_started: formattedTraites.filter(t => t.status === 'not_started').map(t => t.name),
  discord: params.discord
};

return [{ json: response }];

