={
  "embeds": [{
    "title": "{{ $json.type === 'traite_detail' ? '📖 Traité ' + $json.traite : '📚 Statut Global des Traductions' }}",
    "color": {{ $json.statistics.percentage === 100 ? 5763719 : ($json.statistics.percentage > 50 ? 16776960 : 15548997) }},
    "fields": [
      {
        "name": "Progression",
        "value": "{{ $json.statistics.translated }}/{{ $json.statistics.total_pages }} ({{ $json.statistics.percentage }}%)",
        "inline": true
      },
      {
        "name": "En attente",
        "value": "{{ $json.statistics.pending }} pages",
        "inline": true
      },
      {
        "name": "Langue cible",
        "value": "{{ $json.target_language }}",
        "inline": true
      }
      {{ $json.type === 'global_overview' && $json.traites_not_started.length > 0 ? ',{"name": "Non commencés", "value": "' + $json.traites_not_started.slice(0,5).join(', ') + ($json.traites_not_started.length > 5 ? '...' : '') + '", "inline": false}' : '' }}
      {{ $json.type === 'traite_detail' && $json.pending_pages.length > 0 ? ',{"name": "Pages à traduire", "value": "' + $json.pending_pages.slice(0,10).join(', ') + ($json.pending_pages.length > 10 ? '...' : '') + '", "inline": false}' : '' }}
    ],
    "footer": { "text": "Torah Translation Status API" },
    "timestamp": "{{ new Date().toISOString() }}"
  }]
}
